import type{MedusaRequest,MedusaResponse}from'@medusajs/framework/http';import{ContainerRegistrationKeys,Modules}from'@medusajs/framework/utils';const aid=(r:any)=>r.auth_context?.actor_id||r.auth_context?.auth_identity_id;async function sid(req:any,a:string){const q=req.scope.resolve(ContainerRegistrationKeys.QUERY)as any;const{data}=await q.graph({entity:'seller_member',fields:['seller.id'],filters:{member_id:a},pagination:{take:1}}).catch(()=>({data:[]}));return data?.[0]?.seller?.id}export async function DELETE(req:MedusaRequest,res:MedusaResponse){const seller=await sid(req,aid(req));if(!seller)return res.status(403).json({message:'Seller not found'});const q=req.scope.resolve(ContainerRegistrationKeys.QUERY)as any;const{data}=await q.graph({entity:'product',fields:['id','status','metadata','seller.id'],filters:{id:req.params.id},pagination:{take:1}});const p=data?.[0];if(!p)return res.status(404).json({message:'المنتج غير موجود'});if(p.seller?.id&&p.seller.id!==seller)return res.status(403).json({message:'هذا المنتج لا يخص متجرك'});await(req.scope.resolve(Modules.PRODUCT)as any).updateProducts(p.id,{status:'rejected',metadata:{...(p.metadata||{}),spike_archived:true,spike_archived_at:new Date().toISOString()}});const sp=req.scope.resolve('spike')as any;await sp.createSpikeAuditLogs({actor_id:aid(req),actor_type:'seller',action:'product_archived',entity_type:'product',entity_id:p.id,before:{status:p.status},after:{status:'rejected',archived:true}});res.json({id:p.id,archived:true})}
